sp_widget.client_script:
api.controller = function($scope, $location) {

  $scope.scrollTo = function(id) {
    var el = document.getElementById(id);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  };
};

sp_widget.css:
.am-header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 1000;

  padding: 14px 24px 0 24px;
  background-color: #f9fafb;
  border-bottom: 1px solid #e5e7eb;
}

/* MAIN LAYOUT */
.am-header-content {
  max-width: 1200px;
  margin: 0 auto;

  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
}

/* LEFT: Logo */
.am-logo {
  height: 60px;
}

/* CENTER: Title */
.am-title {
  position: absolute;
  left: 40%;
  transform: translateX(-50%);
  
  font-size: 22px;
  font-weight: 600;
  color: #111827;
}

/* NAVIGATION LINKS */
.am-nav {
  display: flex;
  justify-content: center;
  gap: 24px;
  padding: 10px 0 10px 0;
  margin-top: 8px;
}

.am-nav a {
  color: #0076ce;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  text-decoration: none;
  padding: 4px 12px;
  border-radius: 6px;
  transition: all 0.15s ease;
}

.am-nav a:hover {
  color: #005fa3;
  background: #e8f4fd;
  text-decoration: none;
}

.am-nav a i {
  margin-right: 5px;
  font-size: 12px;
}
